function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 20000) return 'nums needs 1 to 20000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > nums.length)) return 'Each value is a whole number from 1 to nums.length.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is a whole number from 1 to nums.length.';
  return null;
}

