function subarraysWithKDistinct(nums, k) {
  // Try every start, grow the subarray to the right and track its distinct values in a set.
  let result = 0;
  for (let start = 0; start < nums.length; start++) {
    const seen = new Set();
    for (let end = start; end < nums.length; end++) {
      seen.add(nums[end]);
      if (seen.size === k) result++;
      if (seen.size > k) break;
    }
  }
  return result;
}

