function generate(rand, size) {
  const between = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? 2000 : between(1, 10);
  const span = size === 'large' ? (rand() < 0.5 ? between(2, 40) : n) : between(1, n);
  const nums = Array.from({ length: n }, () => between(1, span));
  const k = size === 'large' ? between(1, Math.min(n, span + 5)) : between(1, Math.min(n, span + 1));
  return [nums, k];
}
